          "function": "cavity_geometry",
          "feature": "sampled_grid_clearance_statistics_A__mean",
          "physical_role": "Mean clearance between sampled grid points and covalent surfaces; larger means indicate an overall open framework suitable for electron localization."
        },
        {
          "function": "cavity_geometry",
          "feature": "sampled_grid_clearance_statistics_A__max",
          "physical_role": "Maximum sampled clearance; captures the presence of at least one exceptionally large cavity that can host an anionic electron."
